$ErrorActionPreference='Stop'
$runItem=Get-Item -LiteralPath 'C:\Users\22061\.codex\worktrees\96a3\FPGA_Competition\report\evidence\S2B-T06\ps_connection_debug_20261009_113002_r01'
$rawPath=Join-Path $runItem.FullName 'uart_raw.bin'
$outPath=Join-Path $runItem.FullName 'uart_capture_stdout.log'
$errPath=Join-Path $runItem.FullName 'uart_capture_stderr.log'
$identityPath=Join-Path $runItem.FullName 'uart_capture_identity.json'
if (Test-Path -LiteralPath $identityPath) { throw '采集身份文件已存在，拒绝覆盖' }
$sourcePath='C:\Users\22061\.codex\worktrees\96a3\FPGA_Competition\report\evidence\S2B-T06\ps_smoke_hw_20261009_101728_r01\capture_uart.ps1'
$candidates=@(Get-CimInstance Win32_Process -Filter "Name='pwsh.exe'" | Where-Object { $_.CommandLine.Contains($sourcePath) -and $_.CommandLine.Contains($rawPath) -and $_.CommandLine.Contains('-Port COM4') })
if ($candidates.Count -ne 1) { throw '无法唯一绑定刚启动的本次采集进程' }
$capture=$candidates[0]
$stream=[IO.File]::Open($outPath,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::ReadWrite)
$reader=[IO.StreamReader]::new($stream,[Text.UTF8Encoding]::new($false,$true))
try { $observedOut=$reader.ReadToEnd() } finally { $reader.Dispose() }
if (-not $observedOut.Contains('CAPTURE_OPEN ')) { throw '没有CAPTURE_OPEN，禁止PS初始化' }
$openedRecord=$null
foreach ($line in $observedOut.Split([char]10)) { if ($line.StartsWith('CAPTURE_OPEN ')) { $openedRecord=$line.Substring(13) | ConvertFrom-Json } }
if ($null -eq $openedRecord -or $openedRecord.port -cne 'COM4' -or $openedRecord.raw_path -cne $rawPath) { throw '采集就绪参数不符' }
$identity=[ordered]@{ status='CAPTURE_OPEN'; pid=$capture.ProcessId; parent_pid=$capture.ParentProcessId; creation_time_filetime_utc=[string]$capture.CreationDate.ToFileTimeUtc(); executable_path=$capture.ExecutablePath; command_line=$capture.CommandLine; port='COM4'; raw_path=$rawPath; stop_flag=(Join-Path $runItem.FullName 'stop_capture.flag'); observed_open=$openedRecord; initial_launcher_diagnostic='首次就绪观察的ReadAllText因日志正在写入而失败；未重启/未重复占用串口，改用FileShare.ReadWrite观察同一CAPTURE_OPEN。'; checked_at_utc8=[DateTimeOffset]::UtcNow.ToOffset([TimeSpan]::FromHours(8)).ToString('o') }
$identityText=$identity | ConvertTo-Json -Depth 6
$target=[IO.File]::Open($identityPath,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read)
try { $bytes=[Text.UTF8Encoding]::new($false).GetBytes($identityText+[Environment]::NewLine); $target.Write($bytes,0,$bytes.Length); $target.Flush() } finally { $target.Dispose() }
$identityText

$ErrorActionPreference='Stop'
$runItem=Get-Item -LiteralPath 'C:\Users\22061\.codex\worktrees\96a3\FPGA_Competition\report\evidence\S2B-T06\ps_connection_debug_20261009_113002_r01'
$identity=Get-Content -LiteralPath (Join-Path $runItem.FullName 'hw_server_identity.json') -Raw -Encoding utf8 | ConvertFrom-Json
$native=Get-CimInstance Win32_Process -Filter ("ProcessId="+$identity.native.ProcessId)
$launcher=Get-CimInstance Win32_Process -Filter ("ProcessId="+$identity.launcher_pid)
if ($null -eq $native -or $native.ParentProcessId -ne $identity.native.ParentProcessId -or $native.ExecutablePath -cne $identity.native.ExecutablePath -or [string]$native.CreationDate.ToFileTimeUtc() -cne $identity.native.CreationTimeFileTimeUtc) { throw '本次native服务身份不符，拒绝结束' }
$launcherSaved=@($identity.ancestor_chain | Where-Object { $_.ProcessId -eq $identity.launcher_pid })
if ($launcherSaved.Count -ne 1 -or $null -eq $launcher -or $launcher.ExecutablePath -cne $launcherSaved[0].ExecutablePath -or [string]$launcher.CreationDate.ToFileTimeUtc() -cne $launcherSaved[0].CreationTimeFileTimeUtc -or $native.ParentProcessId -ne $launcher.ProcessId) { throw '本次launcher归属不符，拒绝结束' }
if ((Get-FileHash -LiteralPath $native.ExecutablePath -Algorithm SHA256).Hash.ToLowerInvariant() -cne $identity.native_sha256) { throw '服务可执行文件SHA变化' }
$nativeProcess=Get-Process -Id $native.ProcessId
$launcherProcess=Get-Process -Id $launcher.ProcessId
Stop-Process -Id $native.ProcessId -ErrorAction Stop
if (-not $nativeProcess.WaitForExit(10000)) { throw '本次native服务未退出' }
$launcherExited=$launcherProcess.WaitForExit(5000)
if (-not $launcherExited) {
    $remainingLauncher=Get-CimInstance Win32_Process -Filter ("ProcessId="+$identity.launcher_pid)
    if ($null -eq $remainingLauncher -or [string]$remainingLauncher.CreationDate.ToFileTimeUtc() -cne $launcherSaved[0].CreationTimeFileTimeUtc -or $remainingLauncher.ExecutablePath -cne $launcherSaved[0].ExecutablePath) { throw 'launcher再次核对失败' }
    Stop-Process -Id $identity.launcher_pid
    $launcherExited=$launcherProcess.WaitForExit(5000)
}
if (-not $launcherExited) { throw 'launcher未退出' }
$listeners=@(Get-NetTCPConnection -LocalPort 3121 -State Listen -ErrorAction SilentlyContinue | Select-Object LocalAddress,LocalPort,OwningProcess)
[pscustomobject]@{status='OWNED_SERVER_CLOSED';native_pid=$identity.native.ProcessId;launcher_pid=$identity.launcher_pid;native_exited=$nativeProcess.HasExited;launcher_exited=$launcherProcess.HasExited;remaining_listeners=$listeners;closed_at_utc8=[DateTimeOffset]::UtcNow.ToOffset([TimeSpan]::FromHours(8)).ToString('o');cpu_resume_execution='NOT_RUN'} | ConvertTo-Json -Depth 5

$ErrorActionPreference = 'Stop'
$runItem=Get-Item -LiteralPath 'C:\Users\22061\.codex\worktrees\96a3\FPGA_Competition\report\evidence\S2B-T06\ps_connection_debug_20261009_113002_r01'
$captureItem=Get-Item -LiteralPath 'C:\Users\22061\.codex\worktrees\96a3\FPGA_Competition\report\evidence\S2B-T06\ps_smoke_hw_20261009_101728_r01\capture_uart.ps1'
if ((Get-FileHash -LiteralPath $captureItem.FullName -Algorithm SHA256).Hash.ToLowerInvariant() -ne '3b78f5b54dc7413821400e2c5df3bc1c73a93375b9b71ede9bec42a99e16605d') { throw '采集脚本SHA与静态审查不符' }
$knownPort=@(Get-CimInstance Win32_SerialPort | Where-Object { $_.DeviceID -ceq 'COM4' -and $_.PNPDeviceID -ceq 'USB\VID_10C4&PID_EA60\D02E61162787ED11A536569F9D1CC348' -and $_.Status -ceq 'OK' })
if ($knownPort.Count -ne 1) { throw 'COM4身份发生变化' }
$rawPath=Join-Path $runItem.FullName 'uart_raw.bin'
$stopPath=Join-Path $runItem.FullName 'stop_capture.flag'
$captureOut=Join-Path $runItem.FullName 'uart_capture_stdout.log'
$captureErr=Join-Path $runItem.FullName 'uart_capture_stderr.log'
$identityPath=Join-Path $runItem.FullName 'uart_capture_identity.json'
foreach ($candidate in @($rawPath,$stopPath,$captureOut,$captureErr,$identityPath)) { if (Test-Path -LiteralPath $candidate) { throw "目标已存在，拒绝覆盖：$candidate" } }
$pwshProcess=Get-Process -Id $PID
$pwshItem=Get-Item -LiteralPath $pwshProcess.Path
$argText='-NoProfile -File "'+$captureItem.FullName+'" -Port COM4 -RawPath "'+$rawPath+'" -StopFlagPath "'+$stopPath+'"'
$ownedCapture=Start-Process -FilePath $pwshItem.FullName -ArgumentList $argText -WindowStyle Hidden -PassThru -RedirectStandardOutput $captureOut -RedirectStandardError $captureErr
$clock=[Diagnostics.Stopwatch]::StartNew()
$ready=$false
do {
    if (Test-Path -LiteralPath $captureOut) {
        $outText=[IO.File]::ReadAllText($captureOut,[Text.UTF8Encoding]::new($false,$true))
        if ($outText.Contains('CAPTURE_OPEN ')) { $ready=$true; break }
    }
    if ($ownedCapture.HasExited) { throw '采集进程提前退出，禁止初始化；保留日志' }
    Start-Sleep -Milliseconds 100
} while ($clock.Elapsed.TotalSeconds -lt 10)
if (-not $ready) { throw '10秒内没有串口Open就绪标记，禁止初始化' }
$captureCim=Get-CimInstance Win32_Process -Filter "ProcessId=$($ownedCapture.Id)"
$identity=[ordered]@{ status='CAPTURE_OPEN'; pid=$ownedCapture.Id; creation_time_filetime_utc=[string]$captureCim.CreationDate.ToFileTimeUtc(); executable_path=$captureCim.ExecutablePath; command_line=$captureCim.CommandLine; port='COM4'; port_pnp_id=$knownPort[0].PNPDeviceID; raw_path=$rawPath; stop_flag=$stopPath; checked_at_utc8=[DateTimeOffset]::UtcNow.ToOffset([TimeSpan]::FromHours(8)).ToString('o'); parameters='115200/8N1/no-flow/DTR=false/RTS=false'; source_sha256='3b78f5b54dc7413821400e2c5df3bc1c73a93375b9b71ede9bec42a99e16605d' }
$textIdentity=$identity | ConvertTo-Json -Depth 5
$fs=[IO.File]::Open($identityPath,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read)
try { $bytes=[Text.UTF8Encoding]::new($false).GetBytes($textIdentity+[Environment]::NewLine); $fs.Write($bytes,0,$bytes.Length); $fs.Flush() } finally { $fs.Dispose() }
$textIdentity
